<?php
require __DIR__.'/../../config/bootstrap.php';
use Pharmacy\Auth\Authorization;use Pharmacy\Support\Csrf;
Authorization::requireRole('ADMIN');$message=$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{Csrf::validate((string)($_POST['csrf']??''));$username=trim($_POST['username']??'');$name=trim($_POST['full_name']??'');$password=(string)($_POST['password']??'');$roles=array_values(array_intersect($_POST['roles']??[],['ADMIN','PHARMACIST','INVENTORY','MANAGEMENT_VIEWER']));if($username===''||$name===''||strlen($password)<10||!$roles)throw new DomainException('Username, name, at least one role, and a password of 10+ characters are required.');$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO users(username,full_name,password_hash,active) VALUES(:username,:name,:hash,1)');$s->execute(['username'=>$username,'name'=>$name,'hash'=>password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$ri=$pdo->prepare('INSERT INTO user_roles(user_id,role_id) SELECT :user_id,id FROM roles WHERE code=:code');foreach($roles as $role)$ri->execute(['user_id'=>$uid,'code'=>$role]);$pdo->commit();$message='User created.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$users=$pdo->query("SELECT u.id,u.username,u.full_name,u.active,GROUP_CONCAT(r.code ORDER BY r.code SEPARATOR ', ') roles FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id GROUP BY u.id ORDER BY u.full_name")->fetchAll();$title='Users';require __DIR__.'/../../templates/header.php';?>
<h2 class="page-title">Users & Roles</h2><?php if($message):?><div data-flash="<?=htmlspecialchars($message)?>"></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<div class="row g-3"><div class="col-lg-4"><div class="card"><div class="card-body"><h5>Create User</h5><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(Csrf::token())?>"><div class="mb-2"><label class="form-label">Username</label><input class="form-control" name="username" required></div><div class="mb-2"><label class="form-label">Full Name</label><input class="form-control" name="full_name" required></div><div class="mb-2"><label class="form-label">Password</label><input class="form-control" type="password" name="password" minlength="10" required></div><label class="form-label">Roles</label><?php foreach(['ADMIN'=>'Admin','PHARMACIST'=>'Pharmacist','INVENTORY'=>'Store / Inventory','MANAGEMENT_VIEWER'=>'Management Viewer'] as $k=>$v):?><div class="form-check"><input class="form-check-input" type="checkbox" name="roles[]" value="<?=$k?>" id="r<?=$k?>"><label class="form-check-label" for="r<?=$k?>"><?=$v?></label></div><?php endforeach;?><button class="btn btn-dark mt-3">Create User</button></form></div></div></div><div class="col-lg-8"><div class="card"><div class="card-body"><table class="table datatable"><thead><tr><th>Username</th><th>Name</th><th>Roles</th><th>Status</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=htmlspecialchars($u['username'])?></td><td><?=htmlspecialchars($u['full_name'])?></td><td><?=htmlspecialchars($u['roles']??'')?></td><td><?=$u['active']?'Active':'Inactive'?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require __DIR__.'/../../templates/footer.php';
